import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { vi, describe, it, expect, beforeEach } from 'vitest';
import { Checkout } from './Checkout';
import { CartProvider } from './CartContext';
import { PaymentProvider } from './PaymentContext';

const mockProcessPayment = vi.fn();
const mockClearCart = vi.fn();

const mockCart = {
  items: [{ id: '1', name: 'Owl Figurine', price: 42.00 }],
  total: 42.00,
  clearCart: mockClearCart
};

const wrapper = ({ children }) => (
  <CartProvider value={mockCart}>
    <PaymentProvider value={{ processPayment: mockProcessPayment }}>
      {children}
    </PaymentProvider>
  </CartProvider>
);

describe('Checkout - The Log Sees All', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'ORD-TWIN-PEAKS' });
  });

  describe('Happy Path - Through the Woods', () => {
    it('completes full checkout journey', async () => {
      const user = userEvent.setup();
      const onComplete = vi.fn();
      render(<Checkout onComplete={onComplete} />, { wrapper });

      // Shipping - the first step into darkness
      await user.type(screen.getByLabelText(/street address/i), '123 Black Lodge Lane');
      await user.type(screen.getByLabelText(/city/i), 'Twin Peaks');
      await user.selectOptions(screen.getByLabelText(/state/i), 'WA');
      await user.type(screen.getByLabelText(/zip code/i), '98045');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Payment - the owls observe
      await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
      await user.type(screen.getByLabelText(/expiry/i), '12/25');
      await user.type(screen.getByLabelText(/cvv/i), '123');
      await user.type(screen.getByLabelText(/name on card/i), 'Dale Cooper');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Review and submit
      expect(screen.getByText(/owl figurine/i)).toBeInTheDocument();
      await user.click(screen.getByRole('button', { name: /place order/i }));

      await waitFor(() => {
        expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
      });
      expect(onComplete).toHaveBeenCalledWith('ORD-TWIN-PEAKS');
    });
  });

  describe('Validation - The Log Warns', () => {
    it('displays errors for empty shipping fields', async () => {
      const user = userEvent.setup();
      render(<Checkout />, { wrapper });

      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/street address is required/i)).toBeInTheDocument();
      expect(screen.getByLabelText(/street/i)).toHaveAttribute('aria-invalid', 'true');
    });
  });

  describe('Empty Cart - The Void', () => {
    it('shows empty cart message', () => {
      render(<Checkout />, { 
        wrapper: ({ children }) => (
          <CartProvider value={{ items: [], total: 0, clearCart: vi.fn() }}>
            {children}
          </CartProvider>
        )
      });

      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
    });
  });

  describe('Payment Failure - Fire Walk With Me', () => {
    it('displays error and allows retry', async () => {
      mockProcessPayment.mockRejectedValueOnce(new Error('Card declined'));
      // ... proceed through steps, assert error shown, retry succeeds
    });
  });
});
